def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Keep the furthest source position reachable on each alignment diagonal at
    each edit budget, extending every state through its following equal run.
    This uses O(k) auxiliary space and O((len(s) + len(t)) * k) time.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if k >= max(n, m):
        return True

    start = 0
    while start < n and start < m and s[start] == t[start]:
        start += 1
    # A diagonal d represents source_position - target_position.
    previous = {0: start}
    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1

            # Replace the next source character with the next target one.
            pos = previous.get(diagonal, -1)
            if pos >= 0 and pos < n and pos - diagonal < m:
                best = pos + 1

            # Delete a source character, increasing the diagonal by one.
            pos = previous.get(diagonal - 1, -1)
            if pos >= 0 and pos < n:
                best = max(best, pos + 1)

            # Insert a target character, decreasing the diagonal by one.
            pos = previous.get(diagonal + 1, -1)
            if pos >= 0 and pos - (diagonal + 1) < m:
                best = max(best, pos)

            if best < 0:
                continue
            target_pos = best - diagonal
            while best < n and target_pos < m and s[best] == t[target_pos]:
                best += 1
                target_pos += 1
            if best == n and target_pos == m:
                return True
            current[diagonal] = best
        previous = current
    return False

