from functools import lru_cache


@lru_cache(maxsize=None)
def _count_suffix(remaining: int, digit_sum: int, digit_product: int) -> int:
    """Count beautiful completions; sum zero means no digit has started."""
    if remaining == 0:
        return int(digit_sum > 0 and digit_product % digit_sum == 0)
    if digit_product == 0:
        # A real zero digit makes every completion beautiful.
        return 10 ** remaining

    total = 0
    for digit in range(10):
        if digit_sum == 0 and digit == 0:
            total += _count_suffix(remaining - 1, 0, 1)
        else:
            total += _count_suffix(
                remaining - 1, digit_sum + digit, digit_product * digit
            )
    return total


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = [int(digit) for digit in str(bound)]
    total = 0
    digit_sum = 0
    digit_product = 1
    for index, upper in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(upper):
            if digit_sum == 0 and digit == 0:
                total += _count_suffix(remaining, 0, 1)
            else:
                total += _count_suffix(
                    remaining, digit_sum + digit, digit_product * digit
                )
        if digit_sum != 0 or upper != 0:
            digit_sum += upper
            digit_product *= upper

    return total + int(digit_sum > 0 and digit_product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when the product of its digits is divisible
    by their sum. The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

