def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the fewest adjacent stone-pair moves transforming s into t.

    The board has n stones and two adjacent empty cells, initially and
    finally at positions n and n + 1 (using zero-based positions).
    A move preserves the order of the selected adjacent stones.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # White stones are set bits; the empty pair's start is stored separately.
    # Every move leaves the empty cells adjacent, so this describes the whole
    # board even though black stones and empty cells both have unset bits.
    start_mask = sum(1 << i for i, stone in enumerate(s) if stone == 'W')
    target_mask = sum(1 << i for i, stone in enumerate(t) if stone == 'W')
    start = (start_mask << 4) | n
    target = (target_mask << 4) | n
    front = {start}
    back = {target}
    forward_dist = {start: 0}
    backward_dist = {target: 0}

    # Moves are reversible. Expand a full layer from the smaller frontier.
    while front and back:
        if len(front) > len(back):
            front, back = back, front
            forward_dist, backward_dist = backward_dist, forward_dist
        next_front = set()
        for state in front:
            mask = state >> 4
            empty = state & 15
            distance = forward_dist[state] + 1
            for source in range(n + 1):
                if source <= empty + 1 and source + 1 >= empty:
                    continue
                pair = (mask >> source) & 3
                moved_mask = mask ^ (pair << source) ^ (pair << empty)
                neighbor = (moved_mask << 4) | source
                if neighbor in forward_dist:
                    continue
                if neighbor in backward_dist:
                    return distance + backward_dist[neighbor]
                forward_dist[neighbor] = distance
                next_front.add(neighbor)
        front = next_front
    return -1

