def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count replacements by 1, 2, or 3 with distinct edge-adjacent cells.

    The grid has H rows and W columns, consists of '1', '2', '3',
    and '?', and satisfies 1 <= H * W <= 200. Return the count
    modulo 998244353.
    """
    mod = 998244353

    # Sweep along the longer dimension to keep the frontier small.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    choices = tuple(
        tuple(tuple(c for c in (1, 2, 3) if c != above and c != left)
              for left in range(4))
        for above in range(4)
    )
    # Each two-bit slot stores the last color in its column. Zero marks
    # a column that has not been visited yet.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            clear = ~(3 << shift)
            fixed = 0 if grid[r][c] == "?" else int(grid[r][c])
            nxt = {}
            for state, count in dp.items():
                above = (state >> shift) & 3
                left = (state >> (shift - 2)) & 3 if c else 0
                if fixed:
                    if fixed == above or fixed == left:
                        continue
                    allowed = (fixed,)
                else:
                    allowed = choices[above][left]
                base = state & clear
                for color in allowed:
                    new_state = base | (color << shift)
                    nxt[new_state] = (nxt.get(new_state, 0) + count) % mod
            dp = nxt
            if not dp:
                return 0
    return sum(dp.values()) % mod

