def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t.

    At most k operations are permitted (1 <= k <= 20); both input strings
    may contain up to 500000 characters.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t or max(n, m) <= k:
        return True

    # A diagonal is d = target position - source position.  For each edit
    # budget, retain only the furthest source position on each diagonal,
    # extending every state over its following run of matching characters.
    x = 0
    while x < min(n, m) and s[x] == t[x]:
        x += 1
    previous = {0: x}
    for edits in range(1, k + 1):
        current = {}
        for d in range(max(-edits, -n), min(edits, m) + 1):
            best = -1

            # Replace: advance in both strings.
            old = previous.get(d, -1)
            if old >= 0 and old < n and old + d < m:
                best = old + 1

            # Delete: advance only in the source.
            old = previous.get(d + 1, -1)
            if old >= 0 and old < n:
                best = max(best, old + 1)

            # Insert: advance only in the target.
            old = previous.get(d - 1, -1)
            if old >= 0 and old + d - 1 < m:
                best = max(best, old)

            if best < 0:
                continue
            x, y = best, best + d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            current[d] = x
        previous = current
    return False

