from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree with degrees 1 or 4 and a degree-4 vertex.

    Vertices are numbered from 1 to n. Return -1 if no alkane exists.
    Time and space complexity are O(n).
    """
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    parent = [0] * (n + 1)
    order = [1]
    for u in order:
        for v in adjacency[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # branch[u] includes u and assumes its edge to its parent is selected.
    # Thus u is either a leaf, or uses exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for u in reversed(order):
        a = b = c = d = 0
        children = 0
        for v in adjacency[u]:
            if v == parent[u]:
                continue
            children += 1
            value = branch[v]
            if value > a:
                a, b, c, d = value, a, b, c
            elif value > b:
                b, c, d = value, b, c
            elif value > c:
                c, d = value, c
            elif value > d:
                d = value

        if children >= 3:
            branch[u] = 1 + a + b + c
            if parent[u] != 0:
                # Close this branch with its parent serving as a leaf.
                answer = max(answer, branch[u] + 1)
        if children >= 4:
            # u is the highest vertex and has four child branches.
            answer = max(answer, 1 + a + b + c + d)

    return answer
